use super::*;
#[derive(crate::RetireOwned,crate::NativeReceive)]#[value(crate="crate")]struct OriginalEmptyRecord{}
#[test]
fn original_empty_record_receiving_matches_serde_and_retains_every_cancelled_prefix(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../🔗️sealed-shared-receiver/🧪️tests/🫙️empty/🧫️fixtures/🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){let accepted=case["accepted"].as_bool().unwrap();assert_eq!(serde_json::from_value::<std::collections::BTreeMap<String,serde::de::IgnoredAny>>(case["input"].clone()).is_ok_and(|fields|fields.is_empty()),accepted);for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize))){let original=source(DslValue::from(&case["input"]));let d=<OriginalEmptyRecord as NativeReceive<DslValue>>::receive_birth_demand();let(mut receiver,p)=<OriginalEmptyRecord as NativeReceive<DslValue>>::begin_receive(funded(d)).unwrap();assert!(p.fits(funded(d)));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut refused=false;for _ in 0..cut.unwrap_or(10000){if receiver.output_ready(){break;}let d=match receiver.demands(original.borrow(),4096){Ok(d)=>d,Err(_)=>{refused=true;break;}};let g=funded(d);let mut denied=g;denied.maximum_items=0;let(s,h)=semio_framework_value_testing_allocator::observe_retirement_allocations(||advance_original(&mut receiver,original.borrow(),&mut control,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));let(result,h)=semio_framework_value_testing_allocator::observe_retirement_allocations(||advance_original(&mut receiver,original.borrow(),&mut control,g));match result{Ok(s)=>{assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));},Err(e)=>{assert!(e.retained_progress().fits(g));assert_eq!(h,(e.retained_progress().retained_capacity_bytes,e.retained_progress().released_bytes));refused=true;break;}}}if cut.is_none(){assert_eq!(receiver.output_ready(),accepted);assert_eq!(refused,!accepted);}if receiver.output_ready(){let(output,p)=receiver.take(funded(receiver.take_demand().unwrap())).unwrap().unwrap();assert!(p.copied_items>0);drain(output);}receiver.begin_close();for _ in 0..100000{if receiver.terminal_is_empty(){break;}let g=close_funded(receiver.close_demands(4096).unwrap());let(s,h)=semio_framework_value_testing_allocator::observe_retirement_allocations(||receiver.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(receiver.terminal_is_empty());assert_eq!(semio_framework_value_testing_allocator::observe_retirement_allocations(||drop(receiver)).1,(0,0));drain(original);}}
}
